class Solution:
    def solve(self, nums: List[int], queries: List[List[int]]) -> List[int]:
        ans = []
        for l, r, t in queries:
            c = collections.Counter(nums[l:r+1])
            best_f, best_v = 0, -1
            for v, f in c.items():
                if f >= t and (f > best_f or (f == best_f and v < best_v)):
                    best_f, best_v = f, v
            ans.append(best_v)
        return ans

