class Solution {
public:
    vector<int> solve(vector<int>& nums, vector<vector<int>>& queries) {
        vector<int> ans;
        for (auto& qr : queries) {
            unordered_map<int,int> c;
            for (int i = qr[0]; i <= qr[1]; i++) c[nums[i]]++;
            int bf = 0, bv = -1;
            for (auto& [v, f] : c)
                if (f >= qr[2] && (f > bf || (f == bf && v < bv))) { bf = f; bv = v; }
            ans.push_back(bv);
        }
        return ans;
    }
};

