class Solution {
public:
    vector<int> solve(vector<int>& nums, vector<vector<int>>& queries) {
        int n = nums.size(), q = queries.size();
        vector<int> vals(nums); sort(vals.begin(), vals.end());
        vals.erase(unique(vals.begin(), vals.end()), vals.end());
        int m = vals.size();
        vector<int> id(n);
        for (int i = 0; i < n; i++)
            id[i] = lower_bound(vals.begin(), vals.end(), nums[i]) - vals.begin();
        int B = max(1, (int)(n / sqrt((double)q) + 1));
        vector<int> ord(q); iota(ord.begin(), ord.end(), 0);
        sort(ord.begin(), ord.end(), [&](int a, int b){
            int ba = queries[a][0] / B, bb = queries[b][0] / B;
            if (ba != bb) return ba < bb;
            return bb % 2 ? queries[a][1] > queries[b][1] : queries[a][1] < queries[b][1];
        });
        vector<int> cnt(m, 0), fc(n + 2, 0), ans(q);
        vector<priority_queue<int, vector<int>, greater<int>>> heaps(n + 2);
        int cl = 0, cr = -1, maxF = 0;
        auto add = [&](int x){ int f = cnt[x]++; fc[f]--; fc[f+1]++; heaps[f+1].push(x); if (f+1 > maxF) maxF = f+1; };
        auto rem = [&](int x){ int f = cnt[x]--; fc[f]--; fc[f-1]++; if (f == maxF && fc[f] == 0) maxF--; };
        for (int qi : ord) {
            int l = queries[qi][0], r = queries[qi][1], t = queries[qi][2];
            while (cr < r) add(id[++cr]);
            while (cl > l) add(id[--cl]);
            while (cr > r) rem(id[cr--]);
            while (cl < l) rem(id[cl++]);
            auto& h = heaps[maxF];
            while (!h.empty() && cnt[h.top()] != maxF) h.pop();
            ans[qi] = (!h.empty() && maxF >= t) ? h.top() : -1;
        }
        return ans;
    }
};

