class Solution {
    public int[] solve(int[] nums, int[][] queries) {
        int n = nums.length, q = queries.length;
        int[] srt = nums.clone(); Arrays.sort(srt);
        int m = 0;
        for (int i = 0; i < n; i++) if (i == 0 || srt[i] != srt[i-1]) m++;
        int[] vals = new int[m]; int idx = 0;
        for (int i = 0; i < n; i++) if (i == 0 || srt[i] != srt[i-1]) vals[idx++] = srt[i];
        int[] id = new int[n];
        for (int i = 0; i < n; i++) id[i] = Arrays.binarySearch(vals, nums[i]);
        int B = Math.max(1, (int)(n / Math.sqrt(Math.max(1, q)) + 1));
        Integer[] ord = new Integer[q];
        for (int i = 0; i < q; i++) ord[i] = i;
        Arrays.sort(ord, (a, b) -> {
            int ba = queries[a][0] / B, bb = queries[b][0] / B;
            if (ba != bb) return ba - bb;
            return bb % 2 == 0 ? queries[a][1] - queries[b][1] : queries[b][1] - queries[a][1];
        });
        int[] cnt = new int[m], fc = new int[n + 2], ans = new int[q];
        List<PriorityQueue<Integer>> heaps = new ArrayList<>();
        for (int i = 0; i <= n + 1; i++) heaps.add(new PriorityQueue<>());
        int cl = 0, cr = -1, maxF = 0;
        for (int o = 0; o < q; o++) {
            int qi = ord[o], l = queries[qi][0], r = queries[qi][1], t = queries[qi][2];
            while (cr < r) { int x = id[++cr]; int f = cnt[x]++; fc[f]--; fc[f+1]++; heaps.get(f+1).offer(x); if (f+1 > maxF) maxF = f+1; }
            while (cl > l) { int x = id[--cl]; int f = cnt[x]++; fc[f]--; fc[f+1]++; heaps.get(f+1).offer(x); if (f+1 > maxF) maxF = f+1; }
            while (cr > r) { int x = id[cr--]; int f = cnt[x]--; fc[f]--; fc[f-1]++; if (f == maxF && fc[f] == 0) maxF--; }
            while (cl < l) { int x = id[cl++]; int f = cnt[x]--; fc[f]--; fc[f-1]++; if (f == maxF && fc[f] == 0) maxF--; }
            PriorityQueue<Integer> h = heaps.get(maxF);
            while (!h.isEmpty() && cnt[h.peek()] != maxF) h.poll();
            ans[qi] = (!h.isEmpty() && maxF >= t) ? h.peek() : -1;
        }
        return ans;
    }
}

