var solve = function(nums, queries) {
    const n = nums.length, q = queries.length;
    const srt = [...new Set(nums)].sort((a, b) => a - b);
    const idOf = new Map(srt.map((v, i) => [v, i]));
    const id = nums.map(x => idOf.get(x));
    const B = Math.max(1, Math.floor(n / Math.sqrt(Math.max(1, q))) + 1);
    const ord = [...Array(q).keys()].sort((a, b) => {
        const ba = Math.floor(queries[a][0] / B), bb = Math.floor(queries[b][0] / B);
        if (ba !== bb) return ba - bb;
        return bb % 2 === 0 ? queries[a][1] - queries[b][1] : queries[b][1] - queries[a][1];
    });
    const cnt = new Array(srt.length).fill(0), fc = new Array(n + 2).fill(0);
    const heaps = Array.from({length: n + 2}, () => []);
    const hpush = (h, x) => { h.push(x); let i = h.length - 1;
        while (i > 0) { const p = (i - 1) >> 1; if (h[p] <= h[i]) break; [h[p], h[i]] = [h[i], h[p]]; i = p; } };
    const hpop = (h) => { const t = h[0], l = h.pop(); if (h.length) { h[0] = l; let i = 0;
        for (;;) { let c = 2 * i + 1; if (c >= h.length) break; if (c + 1 < h.length && h[c+1] < h[c]) c++;
            if (h[i] <= h[c]) break; [h[i], h[c]] = [h[c], h[i]]; i = c; } } return t; };
    let cl = 0, cr = -1, maxF = 0;
    const add = (x) => { const f = cnt[x]++; fc[f]--; fc[f+1]++; hpush(heaps[f+1], x); if (f+1 > maxF) maxF = f+1; };
    const rem = (x) => { const f = cnt[x]--; fc[f]--; fc[f-1]++; if (f === maxF && fc[f] === 0) maxF--; };
    const ans = new Array(q);
    for (const qi of ord) {
        const [l, r, t] = queries[qi];
        while (cr < r) add(id[++cr]);
        while (cl > l) add(id[--cl]);
        while (cr > r) rem(id[cr--]);
        while (cl < l) rem(id[cl++]);
        const h = heaps[maxF];
        while (h.length && cnt[h[0]] !== maxF) hpop(h);
        ans[qi] = (h.length && maxF >= t) ? h[0] : -1;
    }
    return ans;
};
